function report(k=draft){if(!k||!global.ReportEngine?.printReport)return global.toast?.('Rapor motoru hazır değil.');const original=draft;draft=normalize(k);const cols=draft.sutunlar||[],scoreMode=type==='notCizelgesi'&&draft.hucreModu==='puan',cells=draft.hucreler||{};const heads=cols.map(c=>`<th>${esc(c.baslik||'Sütun')}${c.tarih?`<br><small>${esc(date(c.tarih))}</small>`:''}</th>`).join(''),rows=draft.ogrenciler.map((s,si)=>`<tr><td>${esc(s.no||si+1)}</td><td>${esc(s.ad||'Öğrenci')}</td>${cols.map(c=>`<td style="text-align:center">${esc(displayValue(cells[`${s.id}_${c.id}`]))}</td>`).join('')}${scoreMode?`<td style="text-align:center"><b>${scoreTotal(s.id)}</b></td><td style="text-align:center"><b>${scoreAverage(s.id)}</b></td>`:`<td style="text-align:center"><b>${esc(rowTotal(s.id))}</b></td>`}</tr>`).join(''),summary=scoreMode?'<th>Toplam</th><th>Ortalama</th>':'<th>Toplam</th>',body=`<table><thead><tr><th>No</th><th>Öğrenci</th>${heads}${summary}</tr></thead><tbody>${rows}</tbody></table>`;global.ReportEngine.printReport(draft.ad||label(),body,{fileName:draft.ad||label(),yon:cols.length>5?'yatay':'dikey',ustBaslik:`${draft.sinifAdi||classLabel(draft.sinifId,'')} — ${label()}`});draft=original}
